import{apiClient}from"./client";const adminLogin=async a=>{return(await apiClient.post("/auth/login",a)).data},getAdminCars=async a=>{return(await apiClient.get("/admin/cars",{params:{organizationSlug:a}})).data},createAdminCar=async(a,t)=>{return(await apiClient.post("/admin/cars",a,{params:{organizationSlug:t}})).data},updateAdminCar=async(a,t,i)=>{return(await apiClient.put("/admin/cars/"+a,i,{params:{organizationSlug:t}})).data},deleteAdminCar=async(a,t)=>{return(await apiClient.delete("/admin/cars/"+a,{params:{organizationSlug:t}})).data},getAdminMe=async()=>{return(await apiClient.get("/admin/me")).data},uploadAdminImage=async a=>{const t=new FormData;return t.append("file",a),(await apiClient.post("/admin/media/images",t,{headers:{"Content-Type":"multipart/form-data"}})).data};export{adminLogin,getAdminCars,createAdminCar,updateAdminCar,deleteAdminCar,getAdminMe,uploadAdminImage};